import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
// Bundles the schema files into reviewable SQL files. Never connects to a database.
//   supabase/SETUP.sql                              — the complete structure for an EMPTY database
//   supabase/manual/1_RESET_STRUKTUR_DATABASE.sql   — keep accounts & settings, rebuild, restore (any state)
// --check fails when a generated file is out of date.
const read = file => readFileSync(file, 'utf8').replace(/\r\n/g, '\n')
const names = readdirSync('supabase/schema').filter(name => name.endsWith('.sql')).sort()
const body = names.map(name => '-- supabase/schema/' + name + '\n' + read('supabase/schema/' + name)).join('\n')
const setup = `BEGIN;
DO $$ BEGIN
 IF to_regclass('public.orders') IS NOT NULL THEN
  RAISE EXCEPTION 'Database sudah berisi tabel Printex. Jalankan supabase/manual/1_RESET_STRUKTUR_DATABASE.sql untuk membangun ulang.';
 END IF;
END $$;
${body}
COMMIT;
`
const files = {
  'supabase/SETUP.sql': `-- Generated by npm run db:setup from supabase/schema. Do not edit by hand.
-- Builds the complete Printex database (one production location: Salatiga) in an EMPTY public schema.
-- To rebuild an existing database while keeping accounts, run supabase/manual/1_RESET_STRUKTUR_DATABASE.sql.
${setup}`,
  'supabase/manual/1_RESET_STRUKTUR_DATABASE.sql': `-- LANGKAH 1 — HAPUS SELURUH STRUKTUR DATABASE DAN BANGUN ULANG (satu lokasi: Salatiga)
-- Generated by npm run db:setup from supabase/reset/backup.sql, supabase/schema and
-- supabase/reset/restore.sql. Do not edit by hand. Jalankan seluruh isi file sekaligus di Supabase SQL Editor.
--
-- DIPERTAHANKAN: akun login (password tetap) dengan role Owner/Admin/Operator, waktu kerja, operator standar,
--   kecepatan desain, daftar mesin, link stok, dan nomor Customer Service.
--   Dari database cabang lama hanya akun dan pengaturan Salatiga yang dipertahankan; akun Owner Pusat dan
--   akun cabang lain dihapus.
-- DIHAPUS PERMANEN: semua order, customer, riwayat, laporan, catatan Mulai/Selesai, jam operator, serta
--   seluruh tabel, fungsi dan aturan lama di skema public.
-- Aman dijalankan ulang, juga bila percobaan sebelumnya terhenti di tengah. Dibatalkan tanpa perubahan bila
-- tidak ada akun Owner aktif yang ikut dipertahankan. Setelah selesai, semua pengguna perlu me-refresh halaman.

${read('supabase/reset/backup.sql')}
-- ===== Bagian 2: bangun seluruh struktur database =====
${setup}
${read('supabase/reset/restore.sql')}`,
}
if (process.argv.includes('--check')) {
  for (const [file, output] of Object.entries(files)) {
    if (read(file) !== output) throw new Error(`${file} belum diperbarui. Jalankan npm run db:setup.`)
  }
  console.log('Generated SQL matches its sources.')
} else {
  for (const [file, output] of Object.entries(files)) writeFileSync(file, output)
  console.log('Generated supabase/SETUP.sql and supabase/manual/1_RESET_STRUKTUR_DATABASE.sql. No database was modified.')
}
